parameters.jsCode:
// Extract Meta WhatsApp Payload Details
const body = $input.item.json.body || $input.item.json;

// Check if valid WhatsApp message
const entry = body.entry?.[0];
const change = entry?.changes?.[0];
const value = change?.value;
const message = value?.messages?.[0];
const contact = value?.contacts?.[0];

if (!message) {
  return [];
}

const senderPhone = message.from; // e.g. 923001234567
const senderName = contact?.profile?.name || "Valued Client";
const messageBody = message.text?.body?.toLowerCase() || "";
const messageId = message.id;

return [{
  json: {
    senderPhone,
    senderName,
    messageBody,
    messageId,
    timestamp: new Date().toISOString()
  }
}];

const text = $('Parse Meta Payload').item.json.messageBody;
const name = $('Parse Meta Payload').item.json.senderName;

let replyMessage = "";
let detectedCategory = "none";
let alertPartner = false;

if (text.includes("property") || text.includes("plot") || text.includes("ghar") || text.includes("house") || text.includes("flat")) {
  detectedCategory = "property";
  replyMessage = `Assalam-o-Alaikum ${name}! 🏡 Watech Real Estate mein khush-amdeed.\n\nHamare paas verified listings dastiyab hain:\n1. 1 Kanal Luxury Villa (DHA Phase 6, LHE) - PKR 8.5 Crore\n2. 10 Marla Brand New House (Bahria Town) - PKR 4.2 Crore\n3. 5 Marla Ready Plot (Bahria Phase 8) - PKR 95 Lac\n\nKya aap buy ya rent karna chahte hain? Detail ke liye 1, 2, ya 3 reply karein.`;
  alertPartner = true;
} else if (text.includes("furniture") || text.includes("sofa") || text.includes("wood") || text.includes("bed") || text.includes("dining")) {
  detectedCategory = "furniture";
  replyMessage = `Assalam-o-Alaikum ${name}! 🪑 Watech Authentic Chinioti Furniture catalog:\n\n1. Maharaja Royal Bed Set (Pure Sheesham) - PKR 345,000\n2. Hand-Carved Floral 7-Seater Sofa - PKR 285,000\n3. Antique 8-Seater Dining Suite (Solid Teak) - PKR 395,000\n\nTamam items export-grade polish aur 10-year termite warranty ke sath aate hain. Custom polish ya sizing ke liye reply karein.`;
  alertPartner = true;
} else if (text.includes("event") || text.includes("catering") || text.includes("banquet") || text.includes("hall") || text.includes("marquee")) {
  detectedCategory = "event";
  replyMessage = `Assalam-o-Alaikum ${name}! 🎉 Watech Signature Venues & Catering:\n\n1. Grand Crystal Ballroom (Royal Palm Lahore) - PKR 3,800/head (Desi Menu)\n2. Margalla View Marquee (Islamabad) - PKR 4,500/head (Continental)\n3. Creek Heritage Live BBQ Lawn (Karachi) - PKR 3,200/head (BBQ)\n\nApni expected date aur guest count share karein taake slot lock kiya ja sake.`;
  alertPartner = true;
} else if (text.includes("price") || text.includes("rate") || text.includes("cost") || text.includes("pese")) {
  replyMessage = `Watech Verified Pricing Guide:\n• Plots: PKR 95 Lac se 5 Crore+\n• Luxury Villas: PKR 4.2 Cr se 8.5 Cr+\n• Chinioti Bed Sets: PKR 2.2 Lac se 4.1 Lac\n• Banquet Menu Packages: PKR 2,800 se 4,500 per head.\n\nKis sector ki quotation chahiye?`;
} else if (text.includes("available") || text.includes("khali") || text.includes("slot")) {
  replyMessage = `Ji bilkul! Hamari DHA Phase 6 villa aur Chiniot factory inventory active status par hain. Banquet dates September aur October ke liye open hain.\n\nKripya apna shahar aur requirement batayein.`;
} else {
  replyMessage = `Assalam-o-Alaikum ${name}! Watech Solutions Ecosystem mein khush-amdeed.\n\nKya aap Property, Chinioti Furniture, ya Event Booking ke baare mein maloomat lena chahte hain?\n\n• Type *Property* for Plots & Villas\n• Type *Furniture* for Sheesham Woodwork\n• Type *Event* for Banquet & Catering\n• Or visit: https://watechsolutions.com/marketplace`;
}

return [{
  json: {
    replyMessage,
    detectedCategory,
    alertPartner,
    senderPhone: $('Parse Meta Payload').item.json.senderPhone,
    senderName: $('Parse Meta Payload').item.json.senderName
  }
}];

